CREATE TABLE "c_Admin" ("id" BIGINT NOT NULL, "a_User_email" TEXT NOT NULL, "a_User_created_at" TIMESTAMP NOT NULL, "a_Admin_role_level" BIGINT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Cart" ("id" BIGINT NOT NULL, "a_Cart_status" TEXT NOT NULL, "r_CustomerCart_source_id" BIGINT, PRIMARY KEY ("id"), UNIQUE ("r_CustomerCart_source_id"), CHECK ((TRUE) OR "r_CustomerCart_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_CustomerCart_source_id" IS NOT NULL));
CREATE TABLE "c_Customer" ("id" BIGINT NOT NULL, "a_User_email" TEXT NOT NULL, "a_User_created_at" TIMESTAMP NOT NULL, "a_Customer_loyalty_points" BIGINT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Order" ("id" BIGINT NOT NULL, "a_Order_total" NUMERIC NOT NULL, "a_Order_ordered_at" TIMESTAMP NOT NULL, "r_CustomerOrders_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_CustomerOrders_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_CustomerOrders_source_id" IS NOT NULL));
CREATE TABLE "c_Product" ("id" BIGINT NOT NULL, "a_Product_sku" TEXT NOT NULL, "a_Product_price" NUMERIC NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Review" ("id" BIGINT NOT NULL, "a_Review_rating" BIGINT NOT NULL, "a_Review_body" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_User" ("id" BIGINT NOT NULL, "a_User_email" TEXT NOT NULL, "a_User_created_at" TIMESTAMP NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "l_OrderProducts" ("r_OrderProducts_source_id" BIGINT NOT NULL, "r_OrderProducts_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_OrderProducts_source_id", "r_OrderProducts_target_id"));
CREATE TABLE "l_ProductReviews" ("r_ProductReviews_source_id" BIGINT NOT NULL, "r_ProductReviews_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_ProductReviews_source_id", "r_ProductReviews_target_id"), UNIQUE ("r_ProductReviews_target_id"));
ALTER TABLE "c_Cart" ADD CONSTRAINT "fk_c_Cart_0" FOREIGN KEY ("r_CustomerCart_source_id") REFERENCES "c_Customer" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Order" ADD CONSTRAINT "fk_c_Order_0" FOREIGN KEY ("r_CustomerOrders_source_id") REFERENCES "c_Customer" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_OrderProducts" ADD CONSTRAINT "fk_l_OrderProducts_0" FOREIGN KEY ("r_OrderProducts_source_id") REFERENCES "c_Order" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_OrderProducts" ADD CONSTRAINT "fk_l_OrderProducts_1" FOREIGN KEY ("r_OrderProducts_target_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ProductReviews" ADD CONSTRAINT "fk_l_ProductReviews_0" FOREIGN KEY ("r_ProductReviews_source_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ProductReviews" ADD CONSTRAINT "fk_l_ProductReviews_1" FOREIGN KEY ("r_ProductReviews_target_id") REFERENCES "c_Review" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_ProductReviews"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Review" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_ProductReviews" l WHERE l."r_ProductReviews_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: ProductReviews'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_ProductReviews_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Review" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_ProductReviews"();
CREATE CONSTRAINT TRIGGER "ct_ProductReviews_link" AFTER INSERT OR UPDATE OR DELETE ON "l_ProductReviews" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_ProductReviews"();